-- Elementary watercolor illustrations, batch 3. Upload assets before metadata.
BEGIN;
UPDATE public.word_bank SET example = 'Let''s play with the ball.', example_zh = '我們一起玩球吧。'
WHERE level = 'elementary' AND word = 'ball' AND example = 'a ball of spittle; a fecal ball';
ON CONFLICT (id) DO NOTHING;
COMMIT;
